package com.vandorlabs.neoforge.copifier;
import com.google.gson.*;
import com.vandorlabs.neoforge.glass.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.material.Fluids;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;

/** Installed typed Glass edits preserve identity, orientation, independent fluids and opaque saved fields. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierGlassWorldChecks {
 private static final BlockPos BASE=new BlockPos(15120,100,14640);private static int checks;private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Copifier Glass world: "+why);}
 private static BlockState state(int meta){int size=meta<6?(meta>>1)&3:1;int depth=meta>=6&&meta<10?(meta-4)/2:0;return NativeGlassRegistrations.BLOCK.get().defaultBlockState().setValue(NativeGlassBlock.ROTATED,(meta&1)!=0).setValue(NativeGlassBlock.SIZE,size<3?Math.min(size,1):1).setValue(NativeGlassBlock.DEPTH,depth);}
 private static NativeGlassEntity put(ServerLevel level,BlockPos pos,int meta,CompoundTag data){level.getChunkAt(pos);level.setBlock(pos,Blocks.AIR.defaultBlockState(),18);level.setBlock(pos,state(meta),18);var owner=(NativeGlassEntity)level.getBlockEntity(pos);var supplied=data.copy();supplied.putString("UnrelatedCopiedGlassMarker","retained");owner.loadWithComponents(supplied,level.registryAccess());return owner;}
 private static void write(ServerLevel level)throws Exception{byte[] raw;try(var in=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierGlassReference"))))){raw=in.readAllBytes();}var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,1877),"CopiedGlass"));actor.setGameMode(GameType.SURVIVAL);actor.setPos(BASE.getX()+.5,BASE.getY()+1,BASE.getZ()-2);int captures=0,cases=0;
  for(var element:JsonParser.parseString(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray()){var row=element.getAsJsonObject();int meta=row.get("meta").getAsInt();if(row.has("input")){var source=put(level,BASE,meta,TagParser.parseTag(row.get("input").getAsString()));var before=source.saveWithoutMetadata(level.registryAccess());need(TagParser.parseTag(row.get("capture").getAsString()).equals(NativeCopifierHousingWorld.capture(level,BASE,actor,Direction.NORTH)),"actual Source capture meta="+meta);need(before.equals(source.saveWithoutMetadata(level.registryAccess())),"capture does not rewrite owner");captures++;}
   var owner=put(level,BASE,meta^3,TagParser.parseTag(row.get("target").getAsString()));var state=level.getBlockState(BASE);owner.containedFluids().set(0,new net.neoforged.neoforge.fluids.FluidStack(Fluids.WATER,1000),level.registryAccess());owner.containedFluids().set(1,new net.neoforged.neoforge.fluids.FluidStack(Fluids.LAVA,1000),level.registryAccess());var water=owner.containedFluids().raw(0);var lava=owner.containedFluids().raw(1);var values=TagParser.parseTag(row.get("values").getAsString());var clipboard=values.copy();var before=NativeCopifierHousingWorld.capture(level,BASE,actor,Direction.NORTH);NativeCopifierUndo.begin(actor,level);boolean applied;try{applied=NativeCopifierHousingWorld.applySingle(level,BASE,actor,Direction.NORTH,values);}finally{NativeCopifierUndo.finish(actor);}need(applied==row.get("applied").getAsBoolean(),"Source application result");var expected=TagParser.parseTag(row.get("after").getAsString());need(expected.equals(NativeCopifierHousingWorld.capture(level,BASE,actor,Direction.NORTH)),"Source partial setter projection case="+cases);need(level.getBlockEntity(BASE)==owner&&level.getBlockState(BASE)==state,"same installed owner and metadata");need(owner.saveWithoutMetadata(level.registryAccess()).getString("UnrelatedCopiedGlassMarker").equals("retained")&&owner.containedFluids().raw(0).equals(water)&&owner.containedFluids().raw(1).equals(lava),"unrelated data and both fluid owners unchanged");need(values.equals(clipboard),"clipboard unchanged");if(applied&&!before.equals(expected)){need(NativeCopifierUndo.undo(actor),"Glass settings-only undo");need(before.equals(NativeCopifierHousingWorld.capture(level,BASE,actor,Direction.NORTH))&&owner.containedFluids().raw(0).equals(water)&&owner.containedFluids().raw(1).equals(lava),"undo restores semantic settings without fluid duplication");}cases++;
  }
  put(level,BASE,0,new CompoundTag());put(level,BASE.east(),0,new CompoundTag());var values=new CompoundTag();values.putInt("glass_tint",2);NativeCopifierUndo.begin(actor,level);int applied;try{applied=NativeCopifierHousingConnected.apply(level,BASE,actor,Direction.NORTH,values,false);}finally{NativeCopifierUndo.finish(actor);}need(applied==2,"two connected ordinary Glass owners");need(((NativeGlassEntity)level.getBlockEntity(BASE)).settings().glass().tint==2&&((NativeGlassEntity)level.getBlockEntity(BASE.east())).settings().glass().tint==2,"connected tint applied");need(NativeCopifierUndo.undo(actor)&&((NativeGlassEntity)level.getBlockEntity(BASE.east())).settings().glass().tint==1,"connected Glass undo");need(NativeCopifierHousingWorld.applySingle(level,BASE,actor,Direction.NORTH,values),"saved Glass edit");
  System.out.println("[vandorlabs][copifier-glass-world] write PASS captures="+captures+" cases="+cases+" checks="+checks+" typed owners/Source results/independent fluids/undo/connected");
 }
 private static void read(ServerLevel level){level.getChunkAt(BASE);need(level.getBlockEntity(BASE) instanceof NativeGlassEntity,"saved canonical owner");var owner=(NativeGlassEntity)level.getBlockEntity(BASE);need(owner.settings().glass().tint==2&&owner.saveWithoutMetadata(level.registryAccess()).getString("UnrelatedCopiedGlassMarker").equals("retained"),"copied Glass edit and opaque fields survive process restart");System.out.println("[vandorlabs][copifier-glass-world] read PASS checks="+checks);}
 @SubscribeEvent public static void started(ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.equals("copifier-glass-world-write")&&!phase.equals("copifier-glass-world-read"))return;try{if(phase.endsWith("write"))write(event.getServer().overworld());else read(event.getServer().overworld());event.getServer().saveEverything(true,true,true);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][copifier-glass-world] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
